function updateRootChase(dt){if(!chaseState||!rootChaser||dlg.open)return;const heart=mazeWorld(MAZE_SIZE-2,MAZE_SIZE-2),playerGround=new THREE.Vector3(camera.position.x,0,camera.position.z);if(playerGround.distanceTo(heart)<4.6){if(!chaseState.safe){chaseState.safe=true;const away=rootChaser.position.clone().sub(heart);away.y=0;if(away.length()<5.2)rootChaser.position.copy(heart.clone().add(away.length()>.01?away.normalize().multiplyScalar(5.2):new THREE.Vector3(-5.2,0,0)));document.querySelector('#prompt').textContent='THE HEART PROTECTS YOU — THE CREATURE CANNOT ENTER'}rootChaser.lookAt(camera.position.x,rootChaser.position.y,camera.position.z);return}else if(chaseState.safe){chaseState.safe=false;chaseState.pathTimer=0;document.querySelector('#prompt').textContent='YOU LEFT THE SAFE CHAMBER — RUN'}if(chaseState.headStart>0){chaseState.headStart-=dt;if(chaseState.headStart<=0){rootChaser.visible=true;document.querySelector('#prompt').textContent='RUN — THE PLAYROOM CREATURE FOLLOWED YOU'}return}chaseState.pathTimer-=dt;if(chaseState.pathTimer<=0){chaseState.path=findMazePath(rootChaser.position,camera.position);chaseState.waypoint=1;chaseState.pathTimer=.55}const cell=chaseState.path[chaseState.waypoint];if(cell){const target=mazeWorld(cell[0],cell[1]);target.y=0;const direction=target.clone().sub(rootChaser.position);if(direction.length()<.15)chaseState.waypoint++;else rootChaser.position.add(direction.normalize().multiplyScalar(dt*2.65))}rootChaser.lookAt(camera.position.x,rootChaser.position.y,camera.position.z);if(rootChaser.position.distanceTo(playerGround)<1.05){stability=Math.max(0,stability-20);const start=mazeWorld(1,1);camera.position.set(start.x,1.7,start.z);rootChaser.position.copy(start);chaseState.headStart=3;rootChaser.visible=false;document.querySelector('#prompt').textContent='IT CAUGHT YOU — RUN BEFORE IT WAKES AGAIN'}}
function startMazeEscape(){dlg.close();mazeEscape=true;scene.fog.color.setHex(0x4a0903);scene.fog.density=.032;const open=[];for(let y=0;y<MAZE_SIZE;y++)for(let x=0;x<MAZE_SIZE;x++)if(mazeGrid[y][x]===0){const p=mazeWorld(x,y);open.push(p);mazeEscapePlatforms.push({x:p.x,z:p.z,halfX:.82,halfZ:.82,top:.48})}const lava=new THREE.Mesh(new THREE.PlaneGeometry(MAZE_SIZE*MAZE_CELL,MAZE_SIZE*MAZE_CELL),new THREE.MeshStandardMaterial({color:0xff2705,emissive:0xc31302,emissiveIntensity:3.8,roughness:.35}));lava.rotation.x=-Math.PI/2;lava.position.y=.09;lava.name='maze lava';roomGroup.add(lava);const stones=new THREE.InstancedMesh(new THREE.BoxGeometry(1.65,.45,1.65),mat(0x392b22),open.length),matrix=new THREE.Matrix4();open.forEach((p,index)=>{matrix.makeTranslation(p.x,.255,p.z);stones.setMatrixAt(index,matrix)});stones.castShadow=true;stones.receiveShadow=true;roomGroup.add(stones);playerFeetY=.48;verticalVelocity=0;playerGrounded=true;camera.position.y=2.18;const heart=mazeWorld(MAZE_SIZE-2,MAZE_SIZE-2);spawnRootChaser(heart);chaseState.headStart=2;mazeChaosHandle=setInterval(()=>{if(mazeEscape)mazeShiftTimer=0},650);document.querySelector('#prompt').textContent='ESCAPE! SPACE TO JUMP · THE FLOOR IS LAVA';setTimeout(()=>controls.lock(),100)}
function resetMazeEscape(reason){const heart=mazeWorld(MAZE_SIZE-2,MAZE_SIZE-2);camera.position.set(heart.x,1.7+0.48,heart.z);playerFeetY=.48;verticalVelocity=0;playerGrounded=true;if(rootChaser){rootChaser.position.copy(heart);rootChaser.visible=false}if(chaseState){chaseState.headStart=5;chaseState.pathTimer=0}document.querySelector('#prompt').textContent=`${reason} · FIVE-SECOND HEAD START`}
function updateMazeEscapeHeight(dt){verticalVelocity-=13*dt;const oldFeet=playerFeetY;playerFeetY+=verticalVelocity*dt;let landing=-2;for(const p of mazeEscapePlatforms)if(Math.abs(camera.position.x-p.x)<p.halfX&&Math.abs(camera.position.z-p.z)<p.halfZ&&p.top<=oldFeet+.18)landing=Math.max(landing,p.top);if(playerFeetY<=landing&&verticalVelocity<=0){playerFeetY=landing;verticalVelocity=0;playerGrounded=true}else playerGrounded=false;camera.position.y=playerFeetY+1.7;if(playerFeetY<.12){resetMazeEscape('THE LAVA TOOK YOU');return}const start=mazeWorld(1,1);if(new THREE.Vector2(camera.position.x-start.x,camera.position.z-start.z).length()<1){finishMazeEscape()}}
function updateEscapeChase(dt){if(!chaseState||!rootChaser||dlg.open)return;if(chaseState.headStart>0){chaseState.headStart-=dt;document.querySelector('#prompt').textContent=`HEAD START: ${Math.max(1,Math.ceil(chaseState.headStart))} · RUN AND JUMP`;if(chaseState.headStart<=0){rootChaser.visible=true;document.querySelector('#prompt').textContent='THE MONSTER IS MOVING · RUN'}return}chaseState.pathTimer-=dt;if(chaseState.pathTimer<=0){chaseState.path=findMazePath(rootChaser.position,camera.position);chaseState.waypoint=1;chaseState.pathTimer=.3}const cell=chaseState.path[chaseState.waypoint];if(cell){const target=mazeWorld(cell[0],cell[1]),direction=target.sub(rootChaser.position);direction.y=0;if(direction.length()<.15)chaseState.waypoint++;else rootChaser.position.add(direction.normalize().multiplyScalar(dt*3.35))}rootChaser.lookAt(camera.position.x,1.5,camera.position.z);const distance=new THREE.Vector2(rootChaser.position.x-camera.position.x,rootChaser.position.z-camera.position.z).length();if(distance<1.1)resetMazeEscape('THE MONSTER CAUGHT YOU')}
function finishMazeEscape(){if(!mazeEscape)return;mazeEscape=false;if(mazeChaosHandle){clearInterval(mazeChaosHandle);mazeChaosHandle=null}chaseState=null;if(rootChaser)rootChaser.visible=false;saved[7]=true;localStorage.setItem('cabin-3d-progress',JSON.stringify(saved));updateHud();controls.unlock();message('YOU ESCAPED THE LIVING MAZE','The roots collapse—but instead of the woods, a brass door marked ROOM 13 appears. The Infinite Hotel is now unlocked.')}
function updateHud(){const r=rooms[room];chapter.textContent=r[0];title.textContent=r[1];description.textContent=r[2];objective.textContent=room===0?`${saved[0]?'The inner door is open.':'Repair the door handle.'} Handle ${handlePieces.size}/3 · Cabin secrets ${cabinSecrets.size}/7`:room===8?`${saved[8]?'You checked out.':'Learn the hotel’s rules and reach Floor ∞.'} Impossible room ${Math.min(hotelStage+1,10)}/10`:saved[room]?'The way forward is open.':r[3];count.textContent=`${saved.filter(Boolean).length} / 9`;document.querySelectorAll('#rooms button').forEach((b,i)=>b.classList.toggle('active',i===room));document.querySelector('aside').style.display=room===0?'block':'none'}
function drawMazeMap(){const panel=document.querySelector('#maze-map-panel');if(room!==7||!mazeGrid){panel.style.display='none';return}panel.style.display='block';const canvas=document.querySelector('#maze-map'),ctx=canvas.getContext('2d'),cell=canvas.width/MAZE_SIZE;ctx.fillStyle='#100a07';ctx.fillRect(0,0,canvas.width,canvas.height);for(let y=0;y<MAZE_SIZE;y++)for(let x=0;x<MAZE_SIZE;x++){ctx.fillStyle=mazeGrid[y][x]?'#3f2818':'#9a7950';ctx.fillRect(x*cell,y*cell,Math.ceil(cell),Math.ceil(cell))}const [px,py]=mazeCell(camera.position);ctx.fillStyle='#f3e5bd';ctx.beginPath();ctx.arc((px+.5)*cell,(py+.5)*cell,cell*.42,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#17100b';ctx.lineWidth=1;ctx.stroke();ctx.fillStyle='#65a06c';ctx.fillRect((1+.2)*cell,(1+.2)*cell,cell*.6,cell*.6);const exit=MAZE_SIZE-2,pulse=.42+Math.sin(performance.now()/180)*.12;ctx.fillStyle='#e0372b';ctx.beginPath();ctx.arc((exit+.5)*cell,(exit+.5)*cell,cell*pulse,0,Math.PI*2);ctx.fill()}

document.querySelectorAll('#rooms button').forEach(b=>b.onclick=()=>tryChangeRoom(+b.dataset.room));
document.addEventListener('keydown',e=>{keys[e.code]=true;if(/^Digit[1-9]$/.test(e.code)&&!combat)tryChangeRoom(+e.code.slice(-1)-1);if(e.code==='KeyE')interact();if(e.code==='KeyF')swingBat();if(e.code==='Space'){e.preventDefault();jumpPlayer()}});document.addEventListener('keyup',e=>keys[e.code]=false);
canvas.onclick=()=>{if(!controls.isLocked&&!dlg.open&&!intro.open)controls.lock();else if(combat)swingBat();else if(controls.isLocked)interact()};
function interact(){const ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2(),camera);const hit=ray.intersectObjects(interactables)[0];if(hit&&hit.distance<4.5){const data=hit.object.userData;if(data.type==='story-choice')chooseStory(data.part);else if(data.type==='handle')collectHandle(data.part,hit.object);else if(data.type==='door')enterDoor(data.part);else if(data.type==='bat')collectBat();else if(data.type==='creature')startCombat();else if(data.type==='bonus')openBonusPuzzle(data.part);else if(data.type==='cabin-secret')openCabinSecret(data.part);else if(data.type==='hotel-painting')inspectHotelPainting();else if(data.type==='hotel-door')chooseHotelDoor(data.part);else if(data.type==='hotel-elevator')openHotelElevator();else if(data.type==='hotel-stage')handleHotelStage(data.part);else openPuzzle(data.room)}}
function rootMazeRequirements(){const chapters=saved.slice(0,7).filter(Boolean).length,hidden=requiredBonusPuzzles.filter(id=>bonusSolved.has(id)).length,secrets=requiredCabinSecrets.filter(id=>cabinSecrets.has(id)).length;return{chapters,hidden,secrets,complete:chapters===7&&hidden===requiredBonusPuzzles.length&&secrets===requiredCabinSecrets.length}}
function tryChangeRoom(target){if(target===7){const gate=rootMazeRequirements();if(!gate.complete){controls.unlock();message('THE ROOT CHAMBER IS SEALED',`The roots demand every secret first. Chapter puzzles: ${gate.chapters}/7 · Hidden puzzles: ${gate.hidden}/6 · Cabin secrets: ${gate.secrets}/7. Return to the unfinished rooms.`);return false}}if(combat)stopCombat();room=target;buildRoom(room);return true}
function saveHotelProgress(id){hotelProgress.add(id);localStorage.setItem('infinite-hotel-progress',JSON.stringify([...hotelProgress]))}
function advanceHotelStage(name,copy){hotelStage++;localStorage.setItem('infinite-hotel-stage',hotelStage);saveHotelProgress(`stage-${hotelStage}`);buildRoom(8);controls.unlock();message(name,copy)}
