function updatePlayroomHeight(dt){const crouched=keys.KeyC||keys.ControlLeft||keys.ControlRight,eyeHeight=crouched?.95:1.7;verticalVelocity-=13*dt;const oldFeet=playerFeetY;playerFeetY+=verticalVelocity*dt;let landing=0;for(const p of playroomPlatforms)if(Math.abs(camera.position.x-p.x)<p.halfX+.25&&Math.abs(camera.position.z-p.z)<p.halfZ+.25&&p.top<=oldFeet+.18)landing=Math.max(landing,p.top);if(playerFeetY<=landing&&verticalVelocity<=0){playerFeetY=landing;verticalVelocity=0;playerGrounded=true}else playerGrounded=false;camera.position.y=playerFeetY+eyeHeight}
function animate(){requestAnimationFrame(animate);const now=performance.now(),dt=Math.min(.05,(now-previous)/1000),time=now*.001;previous=now;if(controls.isLocked){const before=camera.position.clone(),crouched=keys.KeyC||keys.ControlLeft||keys.ControlRight,speed=(mazeEscape?4.4:combat?3.8:3.2)*(crouched?.48:1)*dt;if(keys.KeyW||keys.ArrowUp)controls.moveForward(speed);if(keys.KeyS||keys.ArrowDown)controls.moveForward(-speed);if(keys.KeyA||keys.ArrowLeft)controls.moveRight(-speed);if(keys.KeyD||keys.ArrowRight)controls.moveRight(speed);if(room===7&&!inLobby&&mazeBlocked(camera.position)){camera.position.x=before.x;camera.position.z=before.z}const boundary=inLobby?11.3:room===7?(MAZE_SIZE*MAZE_CELL/2-1):room===6?15.6:room===8?13.3:6.3;camera.position.x=THREE.MathUtils.clamp(camera.position.x,-boundary,boundary);camera.position.z=THREE.MathUtils.clamp(camera.position.z,-boundary,boundary);if(room===6&&!inLobby)updatePlayroomHeight(dt);else if(room===7&&mazeEscape&&!inLobby)updateMazeEscapeHeight(dt);else camera.position.y=1.7}if(combat)updateCombat(dt);if(room===7&&!inLobby){updateMovingMaze(dt);if(mazeEscape)updateEscapeChase(dt);else updateRootChase(dt)}if(room===8&&!inLobby)updateHotel(dt);if(dustCloud){dustCloud.rotation.y+=dt*.008;dustCloud.position.y=Math.sin(time*.25)*.08}flickerLights.forEach(l=>l.intensity=l.userData.baseIntensity*(.93+Math.sin(time*11+l.userData.phase)*.035+Math.sin(time*3.7+l.userData.phase)*.025));flashlight.intensity=66+Math.sin(time*7.3)*1.3;drawMazeMap();dolls.forEach(d=>{d.getObjectByName('head').lookAt(camera.position);d.position.lerp(d.userData.origin,dt*3)});renderer.render(scene,camera)}

