function startCombat(){if(saved[6])return message('THE EMPTY PLAYROOM','The spider is gone. Its red ball lies split on the floor.');if(!batOwned){controls.unlock();return message('YOU NEED A WEAPON','The spider lifts the ball beneath its fangs. Find something in the Workshop before facing it.')}combat={phase:'waiting',timer:1.1,hits:0,swing:0,velocity:new THREE.Vector3(),elapsed:0};const mesh=new THREE.Mesh(new THREE.CylinderGeometry(.055,.12,2.2,12),mat(0xa8783f));mesh.rotation.z=-1.15;mesh.position.set(.62,-.58,-1.15);camera.add(mesh);batModel=mesh;document.querySelector('#combat-hud').style.display='block';document.querySelector('#creature-hits').textContent='0 / 5';document.querySelector('#prompt').textContent='WASD MOVE · SPACE JUMP · C CROUCH · CLICK/F SWING';controls.lock()}
