function updateCombat(dt){if(!thrownBall||!creatureModel)return;combat.elapsed+=dt;combat.swing=Math.max(0,combat.swing-dt);creatureModel.userData.legs?.forEach((leg,index)=>{leg.rotation.z=Math.sin(combat.elapsed*9+index*1.7)*.14;leg.rotation.y=Math.sin(combat.elapsed*7+index)*.1;leg.position.y=1.35+Math.sin(combat.elapsed*10+index*Math.PI)*.08});creatureModel.position.y=Math.abs(Math.sin(combat.elapsed*5))*.08;if(batModel)batModel.rotation.z=THREE.MathUtils.lerp(batModel.rotation.z,combat.swing>0?.35:-1.15,Math.min(1,dt*18));if(combat.phase!=='reflected'){const target=new THREE.Vector3(camera.position.x+Math.sin(combat.elapsed*1.9)*2.5,0,camera.position.z+Math.cos(combat.elapsed*1.6)*2.5),direction=target.sub(creatureModel.position);direction.y=0;if(direction.length()>.05)creatureModel.position.add(direction.normalize().multiplyScalar(dt*(1.65+combat.hits*.22)));creatureModel.position.x=THREE.MathUtils.clamp(creatureModel.position.x,-14.5,14.5);creatureModel.position.z=THREE.MathUtils.clamp(creatureModel.position.z,-14.5,14.5);creatureModel.lookAt(camera.position.x,1.5,camera.position.z)}const playerFloor=new THREE.Vector3(camera.position.x,0,camera.position.z),spiderFloor=new THREE.Vector3(creatureModel.position.x,0,creatureModel.position.z);if(playerFloor.distanceTo(spiderFloor)<1.65&&playerFeetY<2.1){spiderCaughtPlayer();return}if(combat.phase==='waiting'){combat.timer-=dt;if(combat.timer<=0){thrownBall.visible=true;thrownBall.position.copy(creatureModel.position).add(new THREE.Vector3(0,1.75,.55));const predicted=camera.position.clone();if(combat.hits>1){const side=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0);predicted.x+=side*(1.1+combat.hits*.2)}combat.velocity.copy(predicted).sub(thrownBall.position).normalize().multiplyScalar(7.2+combat.hits*.85);combat.phase='incoming';document.querySelector('#prompt').textContent='KEEP AWAY FROM THE SPIDER · TOUCHING IT KILLS'}}else if(combat.phase==='incoming'){thrownBall.position.addScaledVector(combat.velocity,dt);const distance=thrownBall.position.distanceTo(camera.position);if(combat.swing>0&&distance<1.55){combat.velocity.copy(creatureModel.position).add(new THREE.Vector3(0,1.7,0)).sub(thrownBall.position).normalize().multiplyScalar(10.5+combat.hits);combat.phase='reflected';document.querySelector('#prompt').textContent='GOOD HIT — KEEP MOVING'}else if(distance<.48){stability=Math.max(0,stability-16);resetThrow('MISSED — DODGE SIDEWAYS OR SWING LATER')}else if(thrownBall.position.length()>35)resetThrow('DODGED — THE SPIDER THROWS AGAIN')}else if(combat.phase==='reflected'){const target=creatureModel.position.clone().add(new THREE.Vector3(0,1.7,0)),desired=target.sub(thrownBall.position).normalize().multiplyScalar(10.5+combat.hits);combat.velocity.lerp(desired,Math.min(1,dt*3));thrownBall.position.addScaledVector(combat.velocity,dt);if(thrownBall.position.distanceTo(creatureModel.position.clone().add(new THREE.Vector3(0,1.7,0)))<.9){combat.hits++;creatureModel.rotation.z+=(combat.hits%2?-.2:.2);document.querySelector('#creature-hits').textContent=`${combat.hits} / 5`;if(combat.hits>=5)winCombat();else resetThrow(`DIRECT HIT ${combat.hits}/5 — THE NEXT THROW IS FASTER`)}}}
