function openPuzzle(i){controls.unlock();if(i===0)return message('THE INNER DOOR',handlePieces.size===3?'The repaired handle turns. Darkness waits beyond.':`Three broken pieces once formed its handle. You have ${handlePieces.size}.`);if(saved[i])return message('CLUE RECOVERED','This room has given up its secret.');if(i===3){const dates=['1987 · CAMP PERMIT','1996 · NEWSPAPER','2008 · CAMERA','TONIGHT · YOUR BACKPACK'],correct=puzzleRun.trophyReverse?[...dates].reverse():dates;return orderPuzzle('THE MISSING HIKERS',correct,3,`Select the belongings from the ${puzzleRun.trophyReverse?'most recent disappearance to the oldest':'oldest disappearance to the most recent'}.`)}if(i===4)return cellarPuzzle();if(i===7)return orderPuzzle('THE LAST BINDING',puzzleRun.mazeBinding,7,'Follow the current runes carved around the heart. Solving them begins the final escape.');const data=i===1?['THE MIRROR’S WARNING',puzzleRun.warning]:['THE CABIN OWNER’S RITUAL',puzzleRun.ritual];orderPuzzle(data[0],data[1],i)}
