 [[3,'RED VALVE · 3 PSI'],[5,'GREEN VALVE · 5 PSI'],[8,'BRASS VALVE · 8 PSI']].forEach(([value,label])=>{
  const button=document.createElement('button');button.textContent=label;
  button.onclick=()=>{if(active.has(value)){active.delete(value);pressure-=value;button.classList.remove('used')}else{active.add(value);pressure+=value;button.classList.add('used')}readout.textContent=`${pressure} PSI`;feedback.textContent=pressure>puzzleRun.cellarTarget?'The pipes shake violently. Pressure is too high.':pressure===puzzleRun.cellarTarget?'The gauge needle rests inside the narrow green band.':'Water continues rising around the hatch.'};
  valves.append(button);
 });
 const drain=document.createElement('button');drain.textContent='ENGAGE DRAIN PUMP';
 drain.onclick=()=>{if(pressure===puzzleRun.cellarTarget){feedback.textContent='The pump roars. Black water spirals away from the hatch.';setTimeout(()=>solve(4),650)}else feedback.textContent=`The safety lock refuses at ${pressure} PSI. The diagram marks exactly ${puzzleRun.cellarTarget}.`};
